import { withPluginApi } from "discourse/lib/plugin-api";

const PLUGIN_ID = "discourse-narrative-bot";

export default {
  name: "narrative-bot-admin-plugin-configuration-nav",

  initialize(container) {
    const currentUser = container.lookup("service:current-user");
    if (!currentUser?.admin) {
      return;
    }

    withPluginApi((api) => {
      api.setAdminPluginIcon(PLUGIN_ID, "robot");
    });
  },
};
import * as Mod1 from "./discourse/initializers/narrative-bot-admin-plugin-configuration-nav";
const compatModules = {
  "discourse/initializers/narrative-bot-admin-plugin-configuration-nav": Mod1,
};
export { compatModules };
export default compatModules;
